#include "../plugins/autolevel/al_storage.cpp"
#include "../plugins/autolevel/al_brush.cpp"
#include "../plugins/autolevel/al_repo_compile.cpp"
#include "../plugins/autolevel/al_solver.cpp"
#include "../plugins/autolevel/al_group_solver.cpp"
#include "../plugins/autolevel/al_default_repo.cpp"
#include "../plugins/autolevel/al_build_map.cpp"
#include <iostream>
using namespace al;
int main(int argc,char** argv){try{auto repo=defaultRepo();if(argc>1)for(auto& bb:repo.bigBlocks){double w=bb.uid=="stair"?std::stod(argv[1]):bb.uid=="hall"&&argc>2?std::stod(argv[2]):bb.uid=="atrium"&&argc>3?std::stod(argv[3]):-1;if(w>=0)for(auto cell:bb.data)for(auto ref:cell)variant(repo,ref)->weight=float(w);}auto rt=compileRepo(repo);EditorSettings settings;std::atomic<bool> cancel{false};std::atomic<float> progress{0};int accepted=0,landmarks=0,minimumLinks=999;double coverage=0,attempts=0,vertical=0,corridors=0;std::vector<double> times;std::cout<<"seed attempts coverage floors stairs+atria halls atria brushes milliseconds\n";for(int seed=1;seed<=30;seed++){auto b=defaultBuilder(repo);integrity(b,rt);b.seed=seed;std::vector<Builder> all{b};auto q=builderRequest(rt,b,all,settings,false,&cancel,&progress);auto start=std::chrono::steady_clock::now();auto solved=solve(q);if(!solved.iterationsUsed)throw std::runtime_error("seed "+std::to_string(seed)+" failed "+solved.failStage);q.layer=1;auto decor=solve(q);if(!decor.iterationsUsed)throw std::runtime_error("decor failed");auto map=buildMap(rt,b,settings,2);double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();auto qual=quality(rt,b.levelData);if(solved.accepted){accepted++;attempts+=solved.iterationsUsed;coverage+=qual.coverage;vertical+=qual.verticalLinks;minimumLinks=std::min(minimumLinks,qual.verticalLinks);corridors+=double(qual.corridors)/std::max(1,qual.walkable);landmarks+=qual.halls+qual.atria>0;if(qual.floors!=3)throw std::runtime_error("accepted layout misses floors");}times.push_back(ms);if(map.brushes>4000)throw std::runtime_error("4000 brush quality budget");std::cout<<seed<<' '<<solved.iterationsUsed<<' '<<qual.coverage<<' '<<qual.floors<<' '<<qual.verticalLinks<<' '<<qual.halls<<' '<<qual.atria<<' '<<map.brushes<<' '<<ms<<'\n';if(seed==1){for(int z=0;z<3;z++){std::cout<<"FLOOR "<<z<<'\n';for(int y=7;y>=0;y--){for(int x=0;x<8;x++){auto& s=rt.states[rt.byHash(b.levelData.layers[0].blocks[index({x,y,z},b.levelData.size)])];char c=s.group==0?'.':s.group==1?'#':s.bigBlockUid=="stair"?'S':s.bigBlockUid=="atrium"?'A':s.bigBlockUid=="hall"?'H':rt.groups[s.group]=="Rooms"?'R':'+';std::cout<<c;}std::cout<<'\n';}}}}
 std::sort(times.begin(),times.end());std::cout<<"SUMMARY accepted="<<accepted<<" attempts="<<attempts/std::max(1,accepted)<<" coverage="<<coverage/std::max(1,accepted)<<" vertical="<<vertical/std::max(1,accepted)<<" minimum="<<minimumLinks<<" landmarks="<<double(landmarks)/std::max(1,accepted)<<" corridor_fraction="<<corridors/std::max(1,accepted)<<" median_ms="<<times[15]<<'\n';if(accepted<29||attempts/accepted>2||coverage/accepted<.55||vertical/accepted<3||minimumLinks<2||double(landmarks)/accepted<.8||corridors/accepted>.65||times[15]>1500)throw std::runtime_error("default quality acceptance threshold");std::cout<<"PASS all default-level quality thresholds\n";
 }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
